'use strict';
const searchField=document.getElementById('partner-search'),categoryField=document.getElementById('partner-category'),cards=[...document.querySelectorAll('.partner-card')],tabs=[...document.querySelectorAll('[data-region]')];
const descriptions={eg:'Technology partners listed for Egypt. Contact NOVA to confirm the scope for your specific project.',gcc:'Technology partners listed for the GCC market. Country coverage varies by partner; contact NOVA for your country.',amu:'Regional partnership for Morocco, Tunisia and Libya.',all:'The complete 33-partner portfolio. Market availability varies by company.'};
const query=new URLSearchParams(location.search);let selectedRegion=['eg','gcc','amu','all'].includes(query.get('region'))?query.get('region'):'eg';
const norm=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
if([...categoryField.options].some(o=>o.value===query.get('category')))categoryField.value=query.get('category');
function filter(){let count=0;cards.forEach(card=>{const match=(selectedRegion==='all'||card.dataset.regions.split(' ').includes(selectedRegion))&&(categoryField.value==='all'||card.dataset.category===categoryField.value)&&norm(card.dataset.name).includes(norm(searchField.value));card.hidden=!match;if(match)count++});tabs.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.region===selectedRegion)));document.getElementById('region-description').textContent=descriptions[selectedRegion];const amuVisible=selectedRegion==='amu'&&(categoryField.value==='all'||categoryField.value==='0')&&norm('De Lama').includes(norm(searchField.value));document.getElementById('amu-partnership').hidden=!amuVisible;document.getElementById('partner-count').textContent=selectedRegion==='amu'?(amuVisible?'1 regional partnership':'0 matching regional partnerships'):count+' matching portfolio partners';document.getElementById('partner-empty').hidden=count>0||amuVisible;}
tabs.forEach(b=>b.addEventListener('click',()=>{selectedRegion=b.dataset.region;filter()}));searchField.addEventListener('input',filter);categoryField.addEventListener('change',filter);document.getElementById('clear-partners').onclick=()=>{searchField.value='';categoryField.value='all';selectedRegion='eg';filter()};filter();
